import { content, type Locale } from "@/content";
import { LocaleProvider } from "@/components/i18n/LocaleProvider";
import { Backdrop } from "@/components/layout/Backdrop";
import { Footer } from "@/components/layout/Footer";
import { Header } from "@/components/layout/Header";
import { Intro } from "@/components/layout/Intro";
import { Hero } from "@/components/hero/Hero";
import { Architecture } from "@/components/sections/Architecture";
import { Beyond } from "@/components/sections/Beyond";
import { Contact } from "@/components/sections/Contact";
import { Curiosity } from "@/components/sections/Curiosity";
import { Path } from "@/components/sections/Path";
import { ProjectGallery } from "@/components/projects/ProjectGallery";
import { homePath } from "@/content/projects";

/**
 * One Night, One Stream — the homepage as a journey:
 * Prologue (the sky) → I Curiosity → II How I engineer → III What I've built
 * → IV The path → Beyond the code → Contact (first light).
 * Section volumes alternate on purpose: loud, quiet, precise, loud, quiet, intimate, calm.
 *
 * One set of components serves every language: server components receive the language's
 * content as `c`; client components read it from the LocaleProvider.
 */
export function Home({ locale }: { locale: Locale }) {
  const c = content[locale];
  return (
    <LocaleProvider locale={locale} alternatePath={homePath(locale === "en" ? "ar" : "en")} onHome>
      <a
        href="#main"
        className="label sr-only z-[100] rounded-full bg-[var(--bg-2)] px-5 py-3 text-xs text-ink focus:not-sr-only focus:fixed focus:start-4 focus:top-4"
      >
        {c.ui.skipToContent}
      </a>
      <Intro />
      <Backdrop />
      <Header />
      <main id="main">
        <Hero c={c} />
        <Curiosity c={c} />
        <Architecture />
        <ProjectGallery />
        <Path c={c} />
        <Beyond c={c} />
        <Contact c={c} />
      </main>
      <Footer c={c} />
    </LocaleProvider>
  );
}
